### `switch-on-type-smell`

```typescript before
function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.r ** 2;
    case "square": return shape.side ** 2;
    case "rectangle": return shape.w * shape.h;
    case "triangle": return (shape.base * shape.h) / 2;
    case "ellipse": return Math.PI * shape.a * shape.b;
    case "rhombus": return (shape.p * shape.q) / 2;
    case "trapezoid": return ((shape.a + shape.b) * shape.h) / 2;
  }
}
```

```typescript after
interface Shape {
  area(): number;
}

function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + shape.area(), 0);
}
```

