## Function shape and single-location smells

### `long-parameter-list`

```typescript before
function createUser(name: string, email: string, age: number, country: string, plan: Plan, referrer: string) {
  return db.users.insert({ name, email, age, country, plan, referrer });
}
```

```typescript after
interface NewUser { name: string; email: string; age: number; country: string; plan: Plan; referrer: string }

function createUser(user: NewUser) {
  return db.users.insert(user);
}
```

### `boolean-parameter`

```typescript before
function renderProfile(user: User, compact: boolean): string {
  return compact ? user.name : `${user.name} (${user.email})`;
}
```

```typescript after
type ProfileLayout = "compact" | "full";

function renderProfile(user: User, layout: ProfileLayout): string {
  return layout === "compact" ? user.name : `${user.name} (${user.email})`;
}
```

### `lack-of-cohesion`

```typescript before
class Account {
  private balance = 0;
  private emails: string[] = [];
  private auditLog: string[] = [];
  deposit(amount: number) { this.balance += amount; }
  addEmail(email: string) { this.emails.push(email); }
  record(entry: string) { this.auditLog.push(entry); }
}
```

```typescript after
class Account {
  private balance = 0;
  deposit(amount: number) { this.balance += amount; }
}

class ContactList {
  private emails: string[] = [];
  addEmail(email: string) { this.emails.push(email); }
}
```

### `type-check-chain`

```typescript before
function describe(event: AppEvent): string {
  if (event instanceof Click) return `click at ${event.x}`;
