### `cognitive-complexity`

```typescript before
function firstOverdue(accounts: Account[], today: Date): Invoice | null {
  for (const account of accounts) {
    if (account.active) {
      for (const invoice of account.invoices) {
        if (invoice.due < today && !invoice.paid) {
          if (invoice.amount > 0 || invoice.fees > 0) {
            return invoice;
          }
        }
      }
    }
  }
  return null;
}
```

```typescript after
function isOverdue(invoice: Invoice, today: Date): boolean {
  return invoice.due < today && !invoice.paid && (invoice.amount > 0 || invoice.fees > 0);
}

function firstOverdue(accounts: Account[], today: Date): Invoice | null {
  const invoices = accounts.filter((account) => account.active).flatMap((account) => account.invoices);
  return invoices.find((invoice) => isOverdue(invoice, today)) ?? null;
}
```

